// The story of Lilith in the Alphabet of Ben Sira, in the original Hebrew, shown untranslated on the Lilith page.
// Copied verbatim from Otzar Midrashim (New York, 1915; public domain), "The Alphabet of ben Sira (alternative version)",
// section 34, as published by Sefaria. Do not edit by hand: the text is reproduced exactly as printed.
export const BEN_SIRA_LILITH = "כשברא הקב״ה אדם הראשון יחיד, אמר לא טוב היות האדם לבדו, ברא לו אשה מן האדמה כמוהו וקראה לילית, מיד התחילו מתגרין זה בזה, אמרה היא איני שוכבת למטה, והוא אומר איני שוכב למטה אלא למעלה שאת ראויה למטה ואני למעלה, אמרה לו שנינו שוין לפי ששנינו מאדמה, ולא היו שומעין זה לזה, כיון שראתה לילית אמרה שם המפורש ופרחה באויר העולם, עמד אדם בתפלה לפני קונו ואמר, רבש״ע אשה שנתת לי ברחה ממני, מיד שגר הקב״ה שלשה מלאכים הללו אחריה להחזירה, אמר לו הקב״ה אם תרצה לחזור מוטב, ואם לאו תקבל על עצמה שימותו מבניה בכל יום מאה בנים, עזבו אותה והלכו אחריה והשיגוה בתוך הים במים עזים שעתידין המצריים לטבוע בו וספרוה דבר ה' ולא רצתה לחזור, אמרו לה אנו נטביעך בים, אמרה להם הניחוני שלא נבראתי אלא להחליש התינוקות כשהן משמונה ימים מיום שיולד אשלוט בו אם הוא זכר, ואם נקבה מיום ילדותה עד עשרים יום. וכששמעו דבריה הפצירו לקחתה, נשבעת להם בשם אל חי וקיים שכל זמן שאני רואה אתכם או שמכם או תבניתכם בקמיע לא אשלוט באותו התינוק, וקבלה על עצמה שימותו מבניה מאה בכל יום, לפיכך בכל יום מתים מאה מן השדים, ולכך אנו כותבים שמותם בקמיע של נערים קטנים ורואה אותם וזוכרת השבועה ומתרפא הילד."

